<?php
declare(strict_types=1); namespace OCA\ERP\Service;
use OCA\ERP\Db\MeasurementAsset; use OCA\ERP\Db\MeasurementAssetMapper; use OCA\ERP\Db\Project; use OCP\IUser;
class MeasurementAssetService { public function __construct(private ErpFolderService $folders,private MeasurementAssetValidator $validator,private MeasurementAssetMapper $assets){} /** @return array{assetFileId:int,mimeType:string} */ public function store(Project $project,IUser $user,string $base64Content):array{$bytes=base64_decode($base64Content,true);if($bytes===false)throw new \InvalidArgumentException('content must be valid base64');$extension=$this->validator->validate($bytes);$folder=$this->folders->ensureMeasurementFolder($user,$project->getProjectNumber() ?? throw new \LogicException('Project Files folder is not configured'));$file=$folder->newFile('aufmass-'.bin2hex(random_bytes(16)).'.'.$extension);$file->putContent($bytes);$mime=match($extension){'png'=>'image/png','jpeg'=>'image/jpeg','pdf'=>'application/pdf'};$asset=new MeasurementAsset();$asset->setProjectId($project->getId());$asset->setFileId($file->getId());$asset->setMimeType($mime);$asset->setCreatedAt(time());$this->assets->insert($asset);return ['assetFileId'=>$file->getId(),'mimeType'=>$mime];} public function assertOwned(int $projectId,int $fileId,string $mimeType):void{$asset=$this->assets->findActive($projectId,$fileId);if($asset===null||$asset->getMimeType()!==$mimeType)throw new \InvalidArgumentException('assetFileId is not a controlled asset for this project');} }
